import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { renderInvoiceText } from '../src/render.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unpublished invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);

  const text = renderInvoiceText(issuedResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows customer name', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText formats single line correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // DEV-HOUR: 9500 cents = €95.00, qty 5 = €475.00
  assert.equal(lines[2], '5x Development (hour) @ €95.00 = €475.00');
});

test('renderInvoiceText formats multiple lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(text.includes('5x Development (hour) @ €95.00 = €475.00'));
  assert.ok(text.includes('2x Design work (hour) @ €85.00 = €170.00'));
  assert.ok(text.includes('3x Copywriting (hour) @ €60.00 = €180.00'));
});

test('renderInvoiceText shows total at the end', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // DEV-HOUR: 9500 * 5 = 47500, discount 5% = 2375, bulk 2226, total disc = 4601, discounted = 42899, VAT 21% = 9009
  // DES-HOUR: 8500 * 2 = 17000, discount 5% = 850, bulk 812, total disc = 1662, discounted = 15338, VAT 21% = 3221
  // Subtotal: 64500, Discount: 6263, VAT: 12230, Total: 70467 cents = €704.67
  assert.ok(text.includes('Total: €704.67'));
  assert.ok(text.includes('VAT: €122.30'));
});

test('renderInvoiceText handles different currency amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 }, // 120000 cents, VAT 21%
      { sku: 'ICON-SET', qty: 2 },  // 980 * 2 = 1960 cents, VAT 21%
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '1x Logo package @ €1,200.00 = €1,200.00');
  assert.equal(lines[3], '2x Icon set (24 icons) @ €9.80 = €19.60');
  // LOGO-PACK: 120000, discount 5% = 6000, discounted = 114000, VAT 21% = 23940
  // ICON-SET: 1960, discount 5% = 98, discounted = 1862, VAT 21% = 391
  // Subtotal: 121960, Discount: 6098, VAT: 24331, Total: 140193 cents = €1,401.93
  assert.equal(lines[lines.length - 1], 'Total: €1,401.93');
  assert.equal(lines[lines.length - 2], 'VAT: €243.31');
});

test('renderInvoiceText with different customer', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText includes all required sections', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // Should have at least: invoice header, customer, line, VAT, total
  assert(lines.length >= 5);
  assert(lines[0].includes('DRAFT') || lines[0].includes('INV-'));
  assert(lines[lines.length - 2].startsWith('VAT: '));
  assert(lines[lines.length - 1].startsWith('Total: '));
});

test('renderInvoiceText formats with thousands separators', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'BRAND-BOOK', qty: 2 }, // 245000 * 2 = 490000, discount 5% = 24500, discounted = 465500, VAT 21% = 97755
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert(lines[2].includes('€2,450.00'));
  // Total: 490000 - 24500 + 97755 = 563255 cents = €5,632.55
  assert(lines[lines.length - 1].includes('€5,632.55'));
  assert(lines[lines.length - 2].includes('€977.55'));
});

test('renderInvoiceText output is readable text', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // Should be a string with newlines
  assert(typeof text === 'string');
  assert(text.includes('\n'));

  // Should have readable formatting
  assert(text.includes('Development (hour)'));
  assert(text.includes('Website hosting (month)'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

test('renderInvoiceText shows VAT line before total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // VAT should be second to last, total should be last
  const lastLineIsTotal = lines[lines.length - 1].startsWith('Total: ');
  const secondLastIsVat = lines[lines.length - 2].startsWith('VAT: ');

  assert(lastLineIsTotal);
  assert(secondLastIsVat);
});

test('renderInvoiceText with 0% VAT lines shows VAT: €0.00', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-03-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // 0% VAT rate
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // WORKSHOP-DAY has 0% VAT
  assert.equal(lines[lines.length - 2], 'VAT: €0.00');
});

// Line discount tests
test('renderInvoiceText shows line discount when present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(text.includes('Discount:'));
});

test('renderInvoiceText hides line discount when not present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // No discount line for this item (C-001 has 5% tier discount but no explicit discount)
  // Actually, C-001 has 5% tier discount applied, so discount should show
  // Let me fix this by using C-002 (standard tier)
  const result2 = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const text2 = renderInvoiceText(result2.value);

  // Should not have "Discount:" for standard tier without explicit discount
  const discountLine = text2.split('\n').find(l => l.includes('Discount:'));
  assert.equal(discountLine, undefined);
});

test('renderInvoiceText shows discount amount correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000 cents
  // Explicit discount 20% = 19000, bulk discount on 76000 = 1900
  // Total discount = 20900
  assert.ok(text.includes('Discount: -'));
});

test('renderInvoiceText with multiple lines and mixed discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // has tier discount
      { sku: 'DES-HOUR', qty: 3, discountPercent: 15 }, // has explicit discount
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // Both lines should have discount shown (tier discount for first, explicit for second)
  const discountLines = text.split('\n').filter(l => l.includes('Discount:'));
  assert.equal(discountLines.length, 2);
});

// Voucher tests
test('renderInvoiceText shows voucher when present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'SUMMER20', amount: 2000 });
  assert.equal(withVoucher.ok, true);

  const text = renderInvoiceText(withVoucher.value);

  assert.ok(text.includes('Voucher'));
  assert.ok(text.includes('SUMMER20'));
});

test('renderInvoiceText shows voucher amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 5000 });
  const text = renderInvoiceText(withVoucher.value);

  assert.ok(text.includes('€50.00'));
});

test('renderInvoiceText omits voucher when not applied', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(!text.includes('Voucher'));
});

// Due date tests
test('renderInvoiceText shows due date when present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(text.includes('Due: 2024-04-14'));
});

test('renderInvoiceText omits due date for draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  // Remove dueDate to test edge case (shouldn't happen in practice)
  const noDueDate = { ...invoiceResult.value };
  delete noDueDate.dueDate;

  const text = renderInvoiceText(noDueDate);
  assert.ok(!text.includes('Due:'));
});

// Paid amount tests
test('renderInvoiceText shows paid amount when payments exist', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const issued = issueInvoice(invoiceResult.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 10000, date: '2024-03-16' });
  assert.equal(payment.ok, true);

  const text = renderInvoiceText(payment.value);

  assert.ok(text.includes('Paid: €100.00'));
});

test('renderInvoiceText omits paid amount when no payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const issued = issueInvoice(invoiceResult.value, []);
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);

  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText aggregates multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const issued = issueInvoice(invoiceResult.value, []);
  const payment1 = recordPayment(issued.value, { amount: 10000, date: '2024-03-16' });
  const payment2 = recordPayment(payment1.value, { amount: 10000, date: '2024-03-17' });

  assert.equal(payment2.ok, true);

  const text = renderInvoiceText(payment2.value);

  // Total paid = 20000 cents = €200.00
  assert.ok(text.includes('Paid: €200.00'));
});

// Combined tests
test('renderInvoiceText with all features', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 5 }],
  });

  assert.equal(invoiceResult.ok, true);

  let invoice = applyVoucher(invoiceResult.value, { code: 'WELCOME', amount: 5000 });
  assert.equal(invoice.ok, true);

  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 25000, date: '2024-03-16' });

  const text = renderInvoiceText(payment.value);

  // Should include discount, voucher, due date, and paid amount
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('Voucher'));
  assert.ok(text.includes('WELCOME'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('Paid:'));
});

test('renderInvoiceText line order', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'TEST', amount: 1000 });
  const issued = issueInvoice(withVoucher.value, []);
  const payment = recordPayment(issued.value, { amount: 10000, date: '2024-03-16' });

  const text = renderInvoiceText(payment.value);
  const lines = text.split('\n');

  // Find the line numbers for key elements
  const totalLineIdx = lines.findIndex(l => l.startsWith('Total:'));
  const voucherLineIdx = lines.findIndex(l => l.includes('Voucher'));
  const dueLineIdx = lines.findIndex(l => l.startsWith('Due:'));
  const paidLineIdx = lines.findIndex(l => l.startsWith('Paid:'));

  // Voucher should come before Total
  assert.ok(voucherLineIdx < totalLineIdx);
  // Due should come after Total
  assert.ok(dueLineIdx > totalLineIdx);
  // Paid should come after Due
  assert.ok(paidLineIdx > dueLineIdx);
});

