import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { renderInvoiceText } from '../src/render.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unpublished invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);

  const text = renderInvoiceText(issuedResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows customer name', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText formats single line correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // DEV-HOUR: 9500 cents = €95.00, qty 5 = €475.00
  assert.equal(lines[2], '5x Development (hour) @ €95.00 = €475.00');
});

test('renderInvoiceText formats multiple lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(text.includes('5x Development (hour) @ €95.00 = €475.00'));
  assert.ok(text.includes('2x Design work (hour) @ €85.00 = €170.00'));
  assert.ok(text.includes('3x Copywriting (hour) @ €60.00 = €180.00'));
});

test('renderInvoiceText shows total at the end', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // DEV-HOUR: 9500 * 5 = 47500, discount 5% = 2375, discounted = 45125, VAT 21% = 9476
  // DES-HOUR: 8500 * 2 = 17000, discount 5% = 850, discounted = 16150, VAT 21% = 3392
  // Subtotal: 64500, Discount: 3225, VAT: 12868, Total: 74143 cents = €741.43
  assert.ok(text.includes('Total: €741.43'));
  assert.ok(text.includes('VAT: €128.68'));
});

test('renderInvoiceText handles different currency amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 }, // 120000 cents, VAT 21%
      { sku: 'ICON-SET', qty: 2 },  // 980 * 2 = 1960 cents, VAT 21%
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '1x Logo package @ €1,200.00 = €1,200.00');
  assert.equal(lines[3], '2x Icon set (24 icons) @ €9.80 = €19.60');
  // LOGO-PACK: 120000, discount 5% = 6000, discounted = 114000, VAT 21% = 23940
  // ICON-SET: 1960, discount 5% = 98, discounted = 1862, VAT 21% = 391
  // Subtotal: 121960, Discount: 6098, VAT: 24331, Total: 140193 cents = €1,401.93
  assert.equal(lines[lines.length - 1], 'Total: €1,401.93');
  assert.equal(lines[lines.length - 2], 'VAT: €243.31');
});

test('renderInvoiceText with different customer', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText includes all required sections', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // Should have at least: invoice header, customer, line, VAT, total
  assert(lines.length >= 5);
  assert(lines[0].includes('DRAFT') || lines[0].includes('INV-'));
  assert(lines[lines.length - 2].startsWith('VAT: '));
  assert(lines[lines.length - 1].startsWith('Total: '));
});

test('renderInvoiceText formats with thousands separators', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'BRAND-BOOK', qty: 2 }, // 245000 * 2 = 490000, discount 5% = 24500, discounted = 465500, VAT 21% = 97755
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  assert(lines[2].includes('€2,450.00'));
  // Total: 490000 - 24500 + 97755 = 563255 cents = €5,632.55
  assert(lines[lines.length - 1].includes('€5,632.55'));
  assert(lines[lines.length - 2].includes('€977.55'));
});

test('renderInvoiceText output is readable text', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  // Should be a string with newlines
  assert(typeof text === 'string');
  assert(text.includes('\n'));

  // Should have readable formatting
  assert(text.includes('Development (hour)'));
  assert(text.includes('Website hosting (month)'));
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

test('renderInvoiceText shows VAT line before total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // VAT should be second to last, total should be last
  const lastLineIsTotal = lines[lines.length - 1].startsWith('Total: ');
  const secondLastIsVat = lines[lines.length - 2].startsWith('VAT: ');

  assert(lastLineIsTotal);
  assert(secondLastIsVat);
});

test('renderInvoiceText with 0% VAT lines shows VAT: €0.00', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-03-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // 0% VAT rate
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // WORKSHOP-DAY has 0% VAT
  assert.equal(lines[lines.length - 2], 'VAT: €0.00');
});

// Line discount tests
test('renderInvoiceText shows line discount when present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.ok(text.includes('Discount:'));
});

test('renderInvoiceText hides line discount when not present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);
  const lines = text.split('\n');

  // No discount line for this item (C-001 has 5% tier discount but no explicit discount)
  // Actually, C-001 has 5% tier discount applied, so discount should show
  // Let me fix this by using C-002 (standard tier)
